#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;

    vector<bool> composite(n + 1, false);
    vector<int> primes;

    for (int i = 2; i <= n; ++i) {
        if (!composite[i]) {
            primes.push_back(i);
            if (1LL * i * i <= n) {
                for (int j = i * i; j <= n; j += i)
                    composite[j] = true;
            }
        }
    }

    int count = 0;
    for (size_t i = 1; i < primes.size(); ++i) {
        int x = primes[i - 1] + primes[i] + 1;
        if (x > n) break;
        if (!composite[x]) ++count;
    }

    cout << (count >= k ? "YES\n" : "NO\n");
    return 0;
}

